using Captovix;
int n=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;Console.WriteLine("PASS: "+name);}
var r=new PixelRect(-500,100,200,100);
Check(CaptureSelection.Hit(r,-500,150,8)==CaptureHandle.Left,"Left side resize on negative monitor");
Check(CaptureSelection.Hit(r,-300,150,8)==CaptureHandle.Right,"Right side resize");
Check(CaptureSelection.Hit(r,-400,100,8)==CaptureHandle.Top,"Top side resize");
Check(CaptureSelection.Hit(r,-400,200,8)==CaptureHandle.Bottom,"Bottom side resize");
Check(CaptureSelection.Hit(r,-500,100,8)==CaptureHandle.TopLeft,"Top left handle");
Check(CaptureSelection.Hit(r,-300,100,8)==CaptureHandle.TopRight,"Top right handle");
Check(CaptureSelection.Hit(r,-500,200,8)==CaptureHandle.BottomLeft,"Bottom left handle");
Check(CaptureSelection.Hit(r,-300,200,8)==CaptureHandle.BottomRight,"Bottom right handle");
Check(CaptureSelection.Hit(r,-400,150,8)==CaptureHandle.Move,"Interior moves existing selection");
Check(CaptureSelection.Hit(r,-900,150,8)==CaptureHandle.New,"Outside starts a new region");
Check(CaptureSelection.Drag(r,CaptureHandle.Top,-400,100,-390,70,false)==new PixelRect(-500,70,200,130),"Top handle changes height alone with fixed opposite edge");
Check(CaptureSelection.Drag(r,CaptureHandle.Left,-500,140,-520,180,false)==new PixelRect(-520,100,220,100),"Left handle ignores vertical motion");
Check(CaptureSelection.Drag(r,CaptureHandle.TopLeft,-500,100,-480,80,false)==new PixelRect(-480,80,180,120),"Corner free resize changes axes independently");
Check(CaptureSelection.Drag(r,CaptureHandle.TopLeft,-500,100,-480,80,true)==new PixelRect(-540,80,240,120),"Shift corner preserves source ratio with opposite corner fixed");
Check(CaptureSelection.Drag(r,CaptureHandle.Top,-400,100,-400,240,false)==new PixelRect(-500,200,200,40),"Crossing opposite edge uses immutable gesture origin");
Check(CaptureSelection.Drag(r,CaptureHandle.Move,-450,120,-430,160,false)==new PixelRect(-480,140,200,100),"Move preserves physical dimensions");
Check(CaptureSelection.Drag(default,CaptureHandle.New,-10,-20,90,80,false)==new PixelRect(-10,-20,100,100),"Manual selection crosses negative desktop coordinates");
Check(CaptureSelection.Drag(default,CaptureHandle.New,0,0,0,50,true)==new PixelRect(0,0,50,50),"Shift vertical drag still produces square");
Check(CaptureSelection.Nudge(r,10,-10,false)==new PixelRect(-490,90,200,100),"Keyboard nudge moves in physical pixels");
Check(CaptureSelection.Nudge(r,10,-10,true)==new PixelRect(-500,100,210,90),"Ctrl arrow resizes independently");
Check(CaptureSelection.Nudge(r,-999,-999,true).Width==8,"Keyboard resize enforces minimum size");
foreach(var scale in new[]{1d,1.25,1.5,1.75,2}){
 double zoom=ImageFidelity.FitZoom(101,99,400,400,scale);
 Check(Math.Abs(ImageFidelity.PhysicalZoom(zoom,scale)-1)<1e-9,"Small capture uses actual pixels at DPI "+scale);
 var fit=ImageFidelity.FitZoom(1600,1200,800,600,scale);
 Check(1600*fit<=800&&1200*fit<=600,"Large capture remains entirely in viewport at DPI "+scale);
}
var screen=new PixelRect(-1920,0,1920,1080);var box=new PixelRect(-1800,100,700,500);
var bar=CaptureSelection.Toolbar(screen,box,350,36);
Check(bar.Intersect(box).IsEmpty&&bar.Intersect(screen)==bar,"Toolbar prefers below content and remains on negative monitor");
bar=CaptureSelection.Toolbar(screen,new(-1800,600,700,480),350,36);Check(bar.Y<600,"Toolbar switches above near bottom edge");
bar=CaptureSelection.Toolbar(screen,screen,350,36);Check(bar.Intersect(screen)==bar&&bar.Height==36,"Full-screen fallback stays compact and inside display");
bar=CaptureSelection.Toolbar(new(0,0,200,100),new(0,0,200,100),450,36);Check(bar.Width==200&&bar.X==0,"Toolbar clamps on small display");
var child=new ElementCandidate(new(-1700,180,300,200),"Bảng",true);var modal=new ElementCandidate(new(-1800,100,700,500),"Modal",true);
var items=ElementSelection.Normalize([modal,child],-1600,220,screen);
var state=new ElementSuggestion();Check(!state.Offer(items,-1600,220,16)&&state.Current==null,"First changed suggestion waits for confirmation");
Check(state.Offer(items,-1600,220,16)&&state.Current?.Bounds==child.Bounds,"Repeated provider result stabilizes suggestion");
state.Cycle(120);Check(state.Current?.Bounds==modal.Bounds,"Wheel selects parent");
state.Offer(items,-1600,220,16);Check(state.Current?.Bounds==modal.Bounds,"Polling preserves deliberate parent selection");
state.Cycle(-120);Check(state.Current?.Bounds==child.Bounds,"Wheel returns to child");
var shifted=items.Select(c=>c with{Bounds=c.Bounds with{X=c.Bounds.X+1}}).ToArray();state.Offer(shifted,-1600,220,16);Check(state.Current?.Bounds==child.Bounds,"One jittered rectangle cannot replace stable frame");
state.Offer(items,-1600,220,16);Check(state.Current?.Bounds==child.Bounds,"Provider returning to stable rectangle cancels jitter");
state.Offer([],-1600,220,16);Check(state.Current?.Bounds==child.Bounds,"Single empty provider response does not flash off highlight");
state.Clear();Check(state.Current==null,"Reset removes stale hierarchy");
var gesture=new CaptureGesture(r,CaptureHandle.Move,-400,150,true);
Check(gesture.Apply(-399,151,false)==r,"Click jitter preserves suggested block for locking");
Check(gesture.Apply(-380,180,false)==new PixelRect(-400,150,20,30)&&gesture.Handle==CaptureHandle.New,"Drag on live suggestion immediately selects manual region");
Check(gesture.Apply(-360,190,false)==new PixelRect(-400,150,40,40),"Continued manual drag keeps initial anchor");
gesture=new CaptureGesture(r,CaptureHandle.Move,-400,150);
Check(gesture.Apply(-380,180,false)==new PixelRect(-480,130,200,100),"Drag after locking moves full selection instead");
gesture=new CaptureGesture(r,CaptureHandle.Top,-400,100);
gesture.Apply(-400,60,false);
Check(gesture.Apply(-400,80,false)==new PixelRect(-500,80,200,120),"Repeated resize events do not accumulate drift");
Console.WriteLine($"{n} smart capture geometry/stability/fidelity checks passed. UIA and overlay interaction require Windows acceptance.");
